window.ScripturaLexicons.BDAG_PART_0325 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0325-01\" data-source=\"BDAG\" data-search=\"σκεπάζω verbo cobrir; proteger; ocultar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σκεπάζω</td><td>verbo</td><td>cobrir; proteger; ocultar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0325-02\" data-source=\"BDAG\" data-search=\"σκέπαρνον, ου, τό substantivo neutro machado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σκέπαρνον, ου, τό</td><td>substantivo neutro</td><td>machado</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0325-03\" data-source=\"BDAG\" data-search=\"σκέπασμα, ατος, τό substantivo neutro cobertura; vestimenta; casa BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σκέπασμα, ατος, τό</td><td>substantivo neutro</td><td>cobertura; vestimenta; casa</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0325-04\" data-source=\"BDAG\" data-search=\"σκέπη, ης, ἡ substantivo feminino sombra; proteção BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σκέπη, ης, ἡ</td><td>substantivo feminino</td><td>sombra; proteção</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0325-05\" data-source=\"BDAG\" data-search=\"σκέπτομαι verbo considerar (?) BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σκέπτομαι</td><td>verbo</td><td>considerar (?)</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0325-06\" data-source=\"BDAG\" data-search=\"Σκευᾶς, ᾶ, ὁ substantivo masculino; nome próprio Ceva BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Σκευᾶς, ᾶ, ὁ</td><td>substantivo masculino; nome próprio</td><td>Ceva</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0325-07\" data-source=\"BDAG\" data-search=\"σκευή, ῆς, ἡ substantivo feminino equipamento; aprestos de navio BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σκευή, ῆς, ἡ</td><td>substantivo feminino</td><td>equipamento; aprestos de navio</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0325-08\" data-source=\"BDAG\" data-search=\"σκεῦος, ους, τό substantivo neutro objeto; recipiente; instrumento; vaso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σκεῦος, ους, τό</td><td>substantivo neutro</td><td>objeto; recipiente; instrumento; vaso</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0325-09\" data-source=\"BDAG\" data-search=\"σκηνή, ῆς, ἡ substantivo feminino tenda; tabernáculo; habitação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σκηνή, ῆς, ἡ</td><td>substantivo feminino</td><td>tenda; tabernáculo; habitação</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0325-10\" data-source=\"BDAG\" data-search=\"σκηνοπηγία, ας, ἡ substantivo feminino Festa dos Tabernáculos; montagem de tendas BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σκηνοπηγία, ας, ἡ</td><td>substantivo feminino</td><td>Festa dos Tabernáculos; montagem de tendas</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0325-11\" data-source=\"BDAG\" data-search=\"σκηνοποιός, οῦ, ὁ substantivo masculino fabricante de adereços cênicos; fabricante de tendas BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σκηνοποιός, οῦ, ὁ</td><td>substantivo masculino</td><td>fabricante de adereços cênicos; fabricante de tendas</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0325-12\" data-source=\"BDAG\" data-search=\"σκῆνος, ους, τό substantivo neutro tenda; alojamento; corpo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σκῆνος, ους, τό</td><td>substantivo neutro</td><td>tenda; alojamento; corpo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0325-13\" data-source=\"BDAG\" data-search=\"σκηνόω verbo habitar; estabelecer-se; abrigar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σκηνόω</td><td>verbo</td><td>habitar; estabelecer-se; abrigar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0325-14\" data-source=\"BDAG\" data-search=\"σκήνωμα, ατος, τό substantivo neutro habitação; morada BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σκήνωμα, ατος, τό</td><td>substantivo neutro</td><td>habitação; morada</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0325-15\" data-source=\"BDAG\" data-search=\"σκῆπτρον, ου, τό substantivo neutro cetro; tribo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σκῆπτρον, ου, τό</td><td>substantivo neutro</td><td>cetro; tribo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0325-16\" data-source=\"BDAG\" data-search=\"σκιά, ᾶς, ἡ substantivo feminino sombra; abrigo; representação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σκιά, ᾶς, ἡ</td><td>substantivo feminino</td><td>sombra; abrigo; representação</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0325-17\" data-source=\"BDAG\" data-search=\"σκιρτάω verbo saltar; exultar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σκιρτάω</td><td>verbo</td><td>saltar; exultar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0325-18\" data-source=\"BDAG\" data-search=\"σκληροκαρδία, ας, ἡ substantivo feminino dureza de coração; obstinação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σκληροκαρδία, ας, ἡ</td><td>substantivo feminino</td><td>dureza de coração; obstinação</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0325-19\" data-source=\"BDAG\" data-search=\"σκληρός, ά, όν adjetivo; substantivado duro; áspero; difícil; inflexível BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σκληρός, ά, όν</td><td>adjetivo; substantivado</td><td>duro; áspero; difícil; inflexível</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0325-20\" data-source=\"BDAG\" data-search=\"σκληρότης, ητος, ἡ substantivo feminino dureza; obstinação; aspereza BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σκληρότης, ητος, ἡ</td><td>substantivo feminino</td><td>dureza; obstinação; aspereza</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0325-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκεπάζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σκεπάζω</span> fut. <span class=\"greek\">σκεπάσω</span> 1 aor. <span class=\"greek\">ἐσκέπασα</span>. Pass.: 1 fut. <span class=\"greek\">σκεπασθήσομαι</span>; 1 aor. <span class=\"greek\">ἐσκεπάσθην</span>; part. perf. n. pl. <span class=\"greek\">ἐσκεπασμένα</span> ParJer 6:4 (<span class=\"greek\">σκέπας</span> ‘cobertura’; X. et al. Aristot.; pap., LXX, pseudepígr.; Mel., P. 84, 632; Philo, Joseph.).</p><p class=\"entry-text\">① estender-se por sobre algo, cobrir (ApcMos 40; ViJer 13; Jos., Ant. 1, 44) <span class=\"greek\">τὶ</span> algo (X. et al.; SibOr 3, 612), de uma árvore que cobre a terra com sua sombra Hs 8, 1, 1; 8, 3, 2; cf. 9, 27, 1. Pass. (cf. Philo, Leg. All. 2, 53) 8, 1, 2.</p><p class=\"entry-text\">② proporcionar segurança, proteger, abrigar (PSI 440, 14 [III a.C.]; PTebt 5, 60 [II a.C.]; PLond III, 897, 6 p. 207 [84 d.C.]; LXX; SibOr 3, 705) <span class=\"greek\">τινά</span> alguém, de bispos, <span class=\"greek\">σκ</span>. <span class=\"greek\">τὰς</span> <span class=\"greek\">χήρας</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">διακονίᾳ</span> abrigar as viúvas por meio de seu ministério Hs 9, 27, 2 (um jogo de palavras com <span class=\"greek\">σκεπάζω</span> 9, 27, 1 [v. 1]). Pass. (PHib 35, 10 [III a.C.]) 1 Cl 60:3; Hs 9, 27, 3. <span class=\"greek\">σκ</span>. <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">μελλόντων</span> <span class=\"greek\">κριμάτων</span> ser protegido dos juízos vindouros 1 Cl 28:1.</p><p class=\"entry-text\">③ manter fora da vista, ocultar <span class=\"greek\">ποῦ</span> … <span class=\"greek\">σκεπάσω</span> <span class=\"greek\">σου</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἀσχημοσύνην</span>; onde ocultarei tua condição embaraçosa?=‘onde esconderei tua gravidez da vista pública?’ GJs 17:3 (cf. TestAbr A 16 p. 97, 1 [Stone 42, 1] <span class=\"greek\">σκέπασόν</span> <span class=\"greek\">σου</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">σαπρίαν</span>).—B. 849. DELG s.v. <span class=\"greek\">σκέπας</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0325-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκέπαρνον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σκέπαρνον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (também masc.; Hom. et al.; LXX, inscr., pap. [I d.C.]) machado GJs 9:1.—DELG s.v. <span class=\"greek\">σκέπαρνος</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0325-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκέπασμα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σκέπασμα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (<span class=\"greek\">σκεπάζω</span>; Pla. et al.) aquilo que serve de cobertura e, por conseguinte, de proteção, cobertura. Principalmente vestimenta (Aristot., Pol. 7, 1336a, 17; Philo, Det. Pot. Ins. 19; Jos., Bell. 2, 129), mas também casa (Aristot., Metaph. 7, 168, 11 <span class=\"greek\">οἰκία</span> <span class=\"greek\">σκέπασμα</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">πλίνθων</span> <span class=\"greek\">κ</span>. <span class=\"greek\">λίθων</span>) com <span class=\"greek\">διατροφή</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:8</a>.—DELG s.v. <span class=\"greek\">σκέπας</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0325-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκέπη, ης, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σκέπη</span>, <span class=\"greek\">ης</span>, <span class=\"greek\">ἡ</span> (cf. <span class=\"greek\">σκεπάζω</span>; Hdt.+; inscr., pap., LXX; JosAs 28:8 [cód. A p. 83, 10 Bat. e Pal 364]; ParJer 6:11; EpArist 140; Manetho: 609 Fgm. 10, 237 Jac. [em Jos., C. Ap. 1, 237]; Jos., Ant. 1, 44; Ath., R. 12 p. 61, 12; 23 p. 76, 30) sombra proporcionada por árvores (cf. Diod S 5, 65, 1; Philo, Sacr. Abel. 25), sugerindo proteção ou segurança Hs 8, 1, 1; 8, 3, 2; 9, 1, 9.—DELG s.v. <span class=\"greek\">σκέπας</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0325-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκέπτομαι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σκέπτομαι</span> (Hom. et al.; pap., LXX; TestSol 1:1 D; Philo, Ath.) a forma pass. é a usual, mas na única ocorrência em nossa lit., somente a voz at.: part. fut. pl. <span class=\"greek\">σ̣κ̣έ̣ψ̣οντες</span> considerar (?) AcPl Ha 1, 12 (texto incerto).—DELG.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0325-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Σκευᾶς, ᾶ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino; nome próprio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Σκευᾶς</span>, <span class=\"greek\">ᾶ</span>, <span class=\"greek\">ὁ</span> (Plut., Caes. 715 [16, 2]; Appian, Bell. Civ. 2, 60 §247 [um centurião: lat. Scaeva]; Cass. Dio 56, 16, 1; B-D-F §125, 2) Ceva, um sumo sacerdote <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:14</a> (segundo EKase, Am. Hist. Review 43, ’38, 437f, um mal-entendido devido à ditografia).—BMastin, JTS 27, ’76, 405–12 (com ref. a CIG 2889, sobre o qual v. LRobert, Les gladiateurs dans l’orient grec ’40, 180ff: um adj. [<span class=\"greek\">σκαιός</span>] que significa ‘canhoto’); BHHW III 1813; Pauly-W. Suppl. IV 931f; II 471–83; Hemer, Acts 234.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0325-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκευή, ῆς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σκευή</span>, <span class=\"greek\">ῆς</span>, <span class=\"greek\">ἡ</span> (Pind., Hdt. et al.; TestSol 5:12; Philo; Jos., Bell. 3, 117, Ant. 4, 301; BGU 775, 6; 11; POslo 187, 6; PWarr 18, 25) um coletivo para uma variedade de objetos que se enquadram na categoria de <span class=\"greek\">σκεῦος</span>, equipamento (empregado alhures a respeito de vestuário, equipamento militar, adereços do coro, etc.); em nossa lit., a respeito dos aprestos ou equipamento de um navio (Diod S 14, 79, 4; Appian, Bell. Civ. 5, 88 §367 [= <span class=\"greek\">τὰ</span> <span class=\"greek\">σκεύη</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πλοίῳ</span> Jon 1:5]) <span class=\"greek\">ἡ</span> <span class=\"greek\">σκευὴ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πλοίου</span>, a respeito do equipamento de um navio de que se pode prescindir <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:19</a> (segundo CVoigt, Die Romfahrt des Ap. Pls: Hansa 53, 1916, 725–32, o aparelho ou cordame de um navio; assim NRSV et al.; v. coments.).—DELG s.v. <span class=\"greek\">σκεῦος</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0325-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκεῦος, ους, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σκεῦος</span>, <span class=\"greek\">ους</span>, <span class=\"greek\">τό</span> (Aristoph., Thu.+)</p><p class=\"entry-text\">① um objeto material empregado para suprir alguma necessidade numa ocupação ou outra responsabilidade, ger. coisa, objeto usado para qualquer finalidade (p. ex., uma mesa: Diod S 17, 66, 5) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:16</a> (PCasey, CBQ 59, ’97, 306–32). <span class=\"greek\">σκεῦος</span> <span class=\"greek\">ἐλεφάντινον</span> ou <span class=\"greek\">ἐκ</span> <span class=\"greek\">ξύλου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.12\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 18:12ab</a>. Pl. (Diod S 13, 12, 6) Dg 2:2–4. De tudo quanto alguém possui (Jos., Vi. 68; 69) <span class=\"greek\">τὰ</span> <span class=\"greek\">σκεύη</span> <span class=\"greek\">αὐτοῦ</span> seus bens <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.31\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 17:31</a>.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:29</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:27</a> (ambos em alusão a Is 49:24f).—Por uma declaração adicional ou pelo contexto, <span class=\"greek\">σκ</span>. pode designar um objeto de uma espécie específica: <span class=\"greek\">τὰ</span> <span class=\"greek\">σκεύη</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">λειτουργίας</span> o equipamento empregado no serviço cultual <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.21\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:21</a> (ParJer 3:9; 11:18; cf. Jos., Bell. 6, 389 <span class=\"greek\">τὰ</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">ἱερουργίας</span> <span class=\"greek\">σκεύη</span>). Também <span class=\"greek\">τὰ</span> <span class=\"greek\">ἅγια</span> <span class=\"greek\">σκεύη</span> Ox 840, 14; 21; 29f (Jos., Bell. 2, 321; cf. Plut., Mor. 812b <span class=\"greek\">σκεῦος</span> <span class=\"greek\">ἱερόν</span>; Philo, Mos. 2, 94; Just., D. 52, 3 <span class=\"greek\">σκεύη</span> <span class=\"greek\">ἱερά</span>). <span class=\"greek\">τὸ</span> <span class=\"greek\">σκεῦος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:17</a> parece ser a âncora de espia ou âncora de arrasto (Breusing 17ff; Blass e Haenchen ad loc.; Voigt [v. <span class=\"greek\">σκευή</span>]. Diversamente HBalmer, Die Romfahrt des Ap. Pls 1905, 355ff. V. FBrannigan, TGl 25, ’33, 182–84; PEdg 6 [=Sb 6712], 10 [258 a.C.] <span class=\"greek\">ἄνευ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀναγκαίων</span> <span class=\"greek\">σκευῶν</span> <span class=\"greek\">πλεῖν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">πλοῖα</span>. Pl. também X., Oec. 8, 11f; ; TestJob 18:7 e alhures, de equipamento de navio; Arrian, Peripl. 5, 2 <span class=\"greek\">τὰ</span> <span class=\"greek\">σκεύη</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ναυτικά</span>. Traduções inglesas apresentam ‘equipamento’, ‘velas’). <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:11</a>, 16; 11:5 representam um estágio de transição para 2.</p><p class=\"entry-text\">② um recipiente de qualquer espécie, vaso, jarro, prato, etc. (Aristoph., Thesm. 402; X., Mem. 1, 7, 5; Aelian, VH 12, 8; Herodian 6, 7, 7; LXX; Jos., Bell. 7, 106; 8, 89; PsSol 17:38; TestNapth 2:2; JosAs; Just., A I, 9, 2 <span class=\"greek\">ἐξ</span> <span class=\"greek\">ἀτίμων</span> … <span class=\"greek\">σκευῶν</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.29\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:29</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:20</a> (quatro espécies, como Plut., Caes. 730 [48, 7]). <span class=\"greek\">τὸ</span> <span class=\"greek\">κενὸν</span> <span class=\"greek\">σκεῦος</span> Hm 11:13. <span class=\"greek\">ποιεῖν</span> <span class=\"greek\">σκ</span>. fazer um vaso 2 Cl 8:2. <span class=\"greek\">τὰ</span> <span class=\"greek\">σκεύη</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">κεραμικά</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.27\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:27</a> (v. <span class=\"greek\">κεραμικός</span>). <span class=\"greek\">σκ</span>. <span class=\"greek\">εἰς</span> <span class=\"greek\">τιμήν</span> ou <span class=\"greek\">εἰς</span> <span class=\"greek\">ἀτιμίαν</span> (v. <span class=\"greek\">τιμή</span> 2b) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.21\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:21</a> (um sentido fig. se faz sentir na última passagem).</p><p class=\"entry-text\">③ um ser humano que exerce uma função, instrumento, vaso, extensão fig. de 1 ou 2 (Polyb. 13, 5, 7 <span class=\"greek\">Δαμοκλῆς</span> <span class=\"greek\">ὑπηρετικὸν</span> <span class=\"greek\">ἦν</span> <span class=\"greek\">ς</span>.); para Cristo, Paulo é um <span class=\"greek\">σκεῦος</span> <span class=\"greek\">ἐκλογῆς</span>, um instrumento escolhido <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:15</a>.—Do corpo, no qual habita o Espírito (cf. TestNapht 8:6 <span class=\"greek\">ὁ</span> <span class=\"greek\">διάβολος</span> <span class=\"greek\">οἰκειοῦται</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">ἴδιον</span> <span class=\"greek\">σκεῦος</span>; ApcMos 16 <span class=\"greek\">γενοῦ</span> <span class=\"greek\">μοι</span> <span class=\"greek\">σκεῦος</span>; e a oração mágica em FPradel, Griech. u. südital. Gebete1907, p. 9, 11f <span class=\"greek\">ἐξορκίζω</span> <span class=\"greek\">σε</span> <span class=\"greek\">ἐξελθεῖν</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">σκεύους</span> <span class=\"greek\">τούτου</span>) Hm 5, 1, 2. O corpo de Cristo como <span class=\"greek\">τὸ</span> <span class=\"greek\">σκ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">πνεύματος</span>, o vaso do Espírito B 7:3; 11:9; cf. <span class=\"greek\">τὸ</span> <span class=\"greek\">καλὸν</span> <span class=\"greek\">σκεῦος</span> 21:8 (do corpo humano, como ApcSed 11:5 [p. 134, 17 Ja.] <span class=\"greek\">ὦ</span> <span class=\"greek\">χεῖρες</span> … <span class=\"greek\">δι</span>’ <span class=\"greek\">ἃς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">σκεῦος</span> <span class=\"greek\">τρέφεται</span>; cf. 10 [l. 25 Ja.]; 11 [l. 27 Ja.]). Sobre o corpo humano como <span class=\"greek\">ὀστράκινα</span> <span class=\"greek\">σκεύη</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.4.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 4:7</a>, v. <span class=\"greek\">ὀστράκινος</span>. Os que se perdem são <span class=\"greek\">σκεύη</span> <span class=\"greek\">ὁργῆς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:22</a> (cf. Jer 27:25.—CDodd, JTS 5, ’54, 247f: instrumentos de juízo; semelhantemente AHanson, JTS 32, ’81, 433–43), os que se salvam <span class=\"greek\">σκ</span>. <span class=\"greek\">ἐλέους</span> v. 23.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:7</a> a mulher é chamada <span class=\"greek\">ἀσθενέστερον</span> <span class=\"greek\">σκεῦος</span> (<span class=\"greek\">ἀσθενής</span> 2a). <span class=\"greek\">τὸ</span> <span class=\"greek\">ἑαυτοῦ</span> <span class=\"greek\">σκεῦος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 4:4</a> desde a antiguidade tem sido interpretado como o próprio corpo (Theodoret, Calvin, Milligan, Schlatter, MDibelius; RKnox, trad. ’44; CCD trad. ’41, marg.; NRSV) ou a própria esposa (Theodore of Mopsuestia, Schmiedel, vDobschütz, Frame, Oepke; WVogel, ThBl 13, ’34, 83–85; RSV et al.). A primeira interpretação é sustentada pelas passagens citadas no início desta seção 3, e a segunda está de acordo com o uso rabínico (Billerb. III 632f. V. também <span class=\"greek\">κτάομαι</span> 1). Também provável para <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 4:4</a> é ‘pênis’ (assim Antistius [I d.C.] em Anthol. Plan. 4, 243; Aelian, NA 17, 11; cf. o lat. eufemístico ‘vasa’ neste sentido: Plautus, Poenulus. 863; v. MPoole, Synopsis Criticorum Ali. Sacrae Script., rev. ed.1694, V col. 908; sobre uso semelhante em Qumran v. TElgvin, NTS 43, ’97, 604–19; NAB [1970] traduz guardando seu membro [diversa a ed. rev. da NAB, 1986]. Cf. KDonfried, NTS 31, ’85, 342). Nesse caso <span class=\"greek\">κτᾶσθαι</span> deve significar algo como ‘obter domínio sobre’, etc.—DELG. M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0325-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκηνή, ῆς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σκηνή</span>, <span class=\"greek\">ῆς</span>, <span class=\"greek\">ἡ</span> (Trag., X., Pla.+; inscr., pap., LXX, TestAbr A; TestJud 25:2; ApcMos, Philo, Joseph., Just.; Tat. 22, 2; Orig., C. Cels. 7, 6, 16)</p><p class=\"entry-text\">① um lugar de abrigo, freq. de alojamentos temporários em contraste com moradas fixas de construção sólida, tenda, cabana</p><p class=\"entry-text\">ⓐ ger. alojamento, habitação, das tendas de nômades (Gen 4:20; 12:8; TestAbr A 1 p. 77, 4 [Stone p. 2].—Dalman, Arbeit VI ’39) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.9\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:9</a>. Da tenda de um soldado <span class=\"greek\">σκηνὴν</span> <span class=\"greek\">πηγνύναι</span> armar uma tenda (<span class=\"greek\">πήγνυμι</span> 2) GPt 8:33. De José no deserto <span class=\"greek\">ἔπηξεν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">σκηνὴν</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">ἐκεῖ</span> GJs 1:4. <span class=\"greek\">δίαιτα</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">σκηνῆς</span> (v. <span class=\"greek\">δίαιτα</span> 2) 1 Cl 56:13 (Job 5:24). <span class=\"greek\">τρεῖς</span> <span class=\"greek\">σκηναί</span> três cabanas (de estruturas temporárias feitas de ramagens) no relato da Transfiguração (com <span class=\"greek\">ποιεῖν</span> como Jos., Ant. 3, 79= armar tendas) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:5</a> (RStein, JBL 95, ’76, 79–86); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.33\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:33</a> (v. <span class=\"greek\">σκηνοπηγία</span> e lit. s.v. <span class=\"greek\">μεταμορφόω</span> 1; esp. ELohmeyer, ZNW 21, 1922, 191ff; HRiesenfeld, Jésus transfiguré ’47, 146–205; HBaltensweiler, Die Verklärung Jesu ’59; WSchmithals, ZTK 69, ’72, 379–411).—Metaf. <span class=\"greek\">ἡ</span> <span class=\"greek\">σκηνὴ</span> <span class=\"greek\">Δαυὶδ</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">πεπτωκυῖα</span> a morada caída de Davi, de seu reino arruinado <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:16</a> (Am 9:11). Aqui <span class=\"greek\">σκηνή</span> talvez signifique tenda do rei (Diod S 17, 36, 4. Mais precisamente 5 <span class=\"greek\">ἡ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Δαρείου</span> <span class=\"greek\">σκηνή</span>; 17, 76, 6 <span class=\"greek\">ἡ</span> <span class=\"greek\">βασιλικὴ</span> <span class=\"greek\">σκηνή</span>): a tenda real caída de Davi.</p><p class=\"entry-text\">ⓑ de uma tenda cultual transportável</p><p class=\"entry-text\"><span class=\"greek\">α</span>. o tabernáculo de Javé <span class=\"greek\">ἡ</span> <span class=\"greek\">σκηνὴ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">μαρτυρίου</span> o Tabernáculo ou Tenda do Testemunho (Ex 27:21; 29:4; Lev 1:1; Num 1:1 e freq.; ViHab 13 [p. 87, 4 Sch.]; Just., D. 36, 2 al.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.44\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:44</a>; 1 Cl 43:2, 5. Também simplesmente <span class=\"greek\">ἡ</span> <span class=\"greek\">σκηνή</span> (LXX; Jos., Ant. 20, 228; Just., D. 127, 3; v. Iren. 1, 18, 2 [Harv. I 171, 15]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.8.5\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 8:5</a>; 9:21; 1 Cl 43:3. <span class=\"greek\">οἱ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">σκ</span>. <span class=\"greek\">λατρεύοντες</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.10\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:10</a> (v. <span class=\"greek\">θυσιαστήριον</span> 1d<span class=\"greek\">γ</span> e OHoltzmann, ZNW 10, 1909, 251–60). <span class=\"greek\">σκηνὴ</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">πρώτη</span> a tenda exterior, i.e., o Lugar Santo 9:2; cf. vv. 6, 8 (<span class=\"greek\">πρῶτος</span> 1c; Jos., C. Ap. 2, 12 apresenta <span class=\"greek\">ἡ</span> <span class=\"greek\">πρώτη</span> <span class=\"greek\">σκηνή</span> do tabernáculo em contraste com o templo de Salomão). Daí <span class=\"greek\">σκηνὴ</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">λεγομένη</span> <span class=\"greek\">Ἅγια</span> <span class=\"greek\">Ἁγίων</span> o Tabernáculo ou Tenda que se chama Santo dos Santos v. 3, <span class=\"greek\">ἡ</span> <span class=\"greek\">δευτέρα</span> (<span class=\"greek\">σκηνή</span>) v. 7.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. o tabernáculo de Moloque <span class=\"greek\">ἡ</span> <span class=\"greek\">σκηνὴ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Μολόχ</span>, do santuário portátil dessa divindade (cf. <span class=\"greek\">ἡ</span> <span class=\"greek\">ἱερὰ</span> <span class=\"greek\">σκηνή</span> dos cartagineses em Diod S 20, 65, 1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.43\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:43</a> (Am 5:26), v. <span class=\"greek\">Μόλοχ</span>.</p><p class=\"entry-text\">② tenda celestial transcendente, tenda, habitação, extensão metaf. de 1. O Tabernáculo terrestre (v. RKittel, RE XIX 33–42 e GBarton, JBL 57, ’38, 197–201) corresponde em Hb a outra <span class=\"greek\">σκηνή</span>: Cristo como Sumo Sacerdote, levando seu próprio sangue (em vez do de bodes e bezerros), vai <span class=\"greek\">διὰ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">μείζονος</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τελειοτέρας</span> <span class=\"greek\">σκηνῆς</span> <span class=\"greek\">ἐφάπαξ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἅγια</span> 9:11f. Ele é <span class=\"greek\">τῶν</span> <span class=\"greek\">ἁγίων</span> <span class=\"greek\">λειτουργὸς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">σκηνῆς</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀληθινῆς</span> 8:2. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.15.5\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 15:5</a> fala de um <span class=\"greek\">ναὸς</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">σκηνῆς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">μαρτυρίου</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">οὐρανῷ</span>. A <span class=\"greek\">σκ</span>.=habitação de Deus está no céu 13:6, e algum dia estará entre os seres humanos 21:3. <span class=\"greek\">αἱ</span> <span class=\"greek\">αἰώνιοι</span> <span class=\"greek\">σκηναί</span> as habitações eternas da vida vindoura <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:9</a> (TestAbr A 20 p. 104, 2 [Stone p. 56] <span class=\"greek\">αἱ</span> <span class=\"greek\">σκηναὶ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">δικαίων</span>; v. RPautrel, ‘Aeterna tabernacula’ [<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:9</a>]: RSR 30, ’40, 307–27; LEby, JBL 58, ’39, p. xi).—OScherling, De Vocis <span class=\"greek\">σκηνή</span> Significatione et Usu, diss. Marburg 1908; HBornhäuser, Sukka ’35, 126–28: <span class=\"greek\">Σκηνή</span> u. verwandte Worte im NT.—B. 461. DELG. OEANE V 179–81. M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0325-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκηνοπηγία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σκηνοπηγία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">σκηνή</span>, <span class=\"greek\">πήγνυμι</span> Aristot., HA 9, 7 da construção de ninhos pelas andorinhas. Alhures somente como termo técnico da linguagem religiosa judaica.—<span class=\"greek\">σκανοπαγέομαι</span> encontra-se como termo técnico religioso numa inscr. [GDI 3632, 11–16] da ilha de Cós [II a.C..—Dssm., LO 92f=LAE 92f]. Sobre <span class=\"greek\">σκηνὴν</span> <span class=\"greek\">πηγνύναι</span> v. <span class=\"greek\">πήγνυμι</span> 2) prim. ‘a armação de tendas’ ou ‘construção de cabanas’. Como nome da Festa das Cabanas/Tabernáculos (<span class=\"greek\">σκ</span>. neste sentido, sobretudo com <span class=\"greek\">ἑορτή</span>: Dt 16:16; 31:10; Zech 14:16, 18, 19; 1 Esdr 5:50; 2 Macc 1:9 [<span class=\"greek\">τὰς</span> <span class=\"greek\">ἡμέρας</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">σκ</span>.]; Jos., Ant. 4, 209; 8, 100; 123; 11, 154; 13, 241; 372; 15, 50, Bell. 2, 515. Inscr. judaica de Berenice na Cirenaica CIG III 5361 [13 a.C.]=Schürer III 94, n. 20, l. 4), festa celebrada em tisri (aproximadamente=outubro), nos dias 15–21, ao ar livre quando possível, em cabanas feitas de ramos de árvores (<span class=\"hebrew\">חַג</span> <span class=\"hebrew\">הַסֻּכּוֹת</span>). Joseph. declara (Ant. 15, 50; cf. 8, 123) que é a festa judaica mais importante. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:1</a> v.l.; 7:2 (CSmith, NTS 9, ’63, 130–46).—Billerb. II 774–812; HBornhäuser, Sukka ’35, esp. pp. 34–39.—Demétrio de Cépsis em Athen. 4, 141ef fala das <span class=\"greek\">τῶν</span> <span class=\"greek\">Καρνείων</span> dos espartanos <span class=\"greek\">σκηναῖς</span> <span class=\"greek\">ἔχοντες</span> <span class=\"greek\">παραπλήσιόν</span> <span class=\"greek\">τι</span>. Eles armam por nove dias ‘algo semelhante a uma tenda’. Às vezes nove homens comem juntos nelas.—GMacRae, The Mng. and Evolution of the Feast of Tabernacles, CBQ 22, ’60, 251–76.—M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0325-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκηνοποιός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σκηνοποιός</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span></p><p class=\"entry-text\">① fabricante de adereços cênicos (segundo Pollux 7, 189, a Comédia Antiga empregava a palavra como sinônimo de <span class=\"greek\">μηχανοποιός</span>=ou um ‘maquinista de teatro’ que movia os adereços cênicos [como Aristoph., Pax 174] ou um ‘fabricante de adereços cênicos’. Entre os termos associados estão <span class=\"greek\">σκηνογράφος</span> Diog. L. 2, 125 e <span class=\"greek\">σκηνογραφία</span> Arist., Poet. 1449a e Polyb. 12, 28a, 1, em ref. à pintura de cenários) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:3</a>. Mas, se se entender <span class=\"greek\">σκηνή</span> não como ‘cenário’, mas como ‘tenda’, e se considerar improvável que Prisca, Áquila e Paulo tenham exercido tal ofício em face de supostas objeções religiosas (v. Schürer II 54–55 sobre as atitudes judaicas para com as representações teatrais), seguir-se-á a tradução tradicional</p><p class=\"entry-text\">② fabricante de tendas. Esta interpretação há muito desfruta de aceitação (v. Lampe s.v.; REB, NRSV; Hemer, Acts 119, 233), mas várias considerações militam contra ela. O termo <span class=\"greek\">σκηνοποιός</span> não é empregado fora da Bíblia (e de sua influência), exceto em Pollux (acima) e Herm. Wr. 516, 10f=Stob. I, 463, 7ff. Ali aparece como adj. e em sentido figurado, concernente à produção de uma morada apropriada para a alma. O contexto, portanto, indica claramente uma estrutura como componente primário, mas, na ausência de tal qualificador em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:3</a>, é necessário levar em conta palavras e expressões que igualmente contêm os termos <span class=\"greek\">σκηνή</span> e <span class=\"greek\">ποιεῖν</span>. Um levantamento do uso indica que <span class=\"greek\">σκηνή</span> aparece freq. como obj. de <span class=\"greek\">ποιέω</span> no sentido de ‘armar’ ou ‘erigir uma tenda’ (v. <span class=\"greek\">ποιέω</span> 1a; at. <span class=\"greek\">σκηνοποιέω</span> Is 13:20 Sym. <span class=\"greek\">οὐδὲ</span> <span class=\"greek\">σκηνοποιήσει</span> <span class=\"greek\">ἐκεῖ</span> <span class=\"greek\">῎</span> <span class=\"greek\">Αραψ</span>; 22:15 Sym.; méd. <span class=\"greek\">σκηνοποιέομαι</span> Aristot., Meteor. 348b, 35; Clearch., Fgm. 48 W.; Polyb. 14, 1, 7; Diod S 3, 27, 4; Ps.-Callisth. 2, 9, 8.—Cf. <span class=\"greek\">σκηνοποιί̈α</span> Aeneas Tact. 8, 3; Polyb. 6, 28, 3; inscr., RevArch 3, ’34, 40; e, segundo a tradição textual de Dt 31:10, como expressão alternativa para <span class=\"greek\">σκηνοπηγία</span>.—Ex 26:1, reconheça-se, oferece prova clara do uso da combinação não composta <span class=\"greek\">σκηνή</span> + <span class=\"greek\">ποιέω</span> no sentido de ‘produzir’ ou ‘fabricar [não armar] uma tenda’, mas o contexto torna inequívoco o significado; cf. Herodian 7, 2, 4 sobre a construção de habitações rudimentares). Analogamente, <span class=\"greek\">σκηνοποιός</span> significaria ‘aquele que arma ou erige tendas’, opção linguisticamente mais provável que a de ‘fabricante de tendas’, mas nas passagens citadas para <span class=\"greek\">σκηνοποιέω</span> e <span class=\"greek\">σκηνοποιί̈α</span> os componentes do contexto (cf. o caso do provimento de habitação na passagem hermética) apontam claramente para a denotação ‘armação de tendas’, ao passo que <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:3</a> carece de tal qualificador claro. Ademais, é questionável se os habitantes de regiões nômades dependeriam de especialistas para auxiliá-los em tarefa tão comum (v. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17:4</a> par., onde se menciona uma espécie relacionada de iniciativa independente).—Também é improvável que Prisca, Áquila e Paulo estivessem empenhados na preparação de peças para a produção de uma tenda, pois tais tarefas teriam sido deixadas aos seus empregados. A possibilidade de que fossem responsáveis por montar uma tenda a partir de várias peças é excluída pela disponibilidade do termo <span class=\"greek\">σκηνορράφος</span> (Ael., VH 2, 1 et al.; Bull. Inst. Arch. Bulg. 8, 69) no sentido de coser as peças umas às outras (o verbo <span class=\"greek\">ἐπιτελεῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.8.5\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 8:5</a> não sustenta tal opinião, pois não é uma expressão alternativa para a ‘produção’ de uma tenda, mas denota a ‘conclusão’ de um empreendimento, com forte conotação de compromisso religioso; v. <span class=\"greek\">ἐπιτελέω</span> 2), no qual o componente <span class=\"greek\">ῥαφ</span>- fornece um qualificador inequívoco.—Em tempos modernos, tem-se dado maior consideração à identificação do ofício de Paulo como ‘trabalhador em couro’, interpretação favorecida por numerosas versões e escritos patrísticos (v. Zahn, AG, ad loc.; L-S-J-M Suppl., s.v., em substituição ao seu anterior ‘fabricante de tendas’; Haenchen, ad loc., seguindo JJeremias, ZNW 30, ’31; Hock, v. abaixo). Como tal, fabricaria tendas e outros produtos de couro (Hock [v. abaixo] 21). Mas este e outros esforços por uma definição mais precisa, como tecelão de tecido para tendas (opinião já fora de voga), podem transmitir reflexos do conhecimento de práticas locais em vez de precisão semântica.—Na ausência de qualquer emprego do termo <span class=\"greek\">σκηνοποιός</span>, além da passagem em Pollux e nos Herm. Wr., e dada a falta de qualificadores específicos no texto de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:3</a>, resta a forte probabilidade de que os públicos de Lucas nas áreas urbanas, onde abundavam representações teatrais, pensassem em <span class=\"greek\">σκηνοποιός</span> em ref. a assuntos teatrais (v. 1). Além disso, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.34\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:34</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 3:8</a> indicam que o trabalho de Paulo era de natureza técnica e era realizado em áreas metropolitanas, onde haveria grande demanda por tal espécie de trabalho. O que os públicos de outras regiões poderiam compreender está sujeito a maior dúvida, pois a evidência é principalmente anedótica.—JWeiss, Das Urchristentum 1917, 135; FGrosheide, <span class=\"greek\">Παῦλος</span> <span class=\"greek\">σκηνοποιός</span>: TSt 35, 1917, 241f; Zahn, AG II 632, 10; 634; Billerb. II 745–47; Beginn. IV, 223; PLampe, BZ 31, ’87, 211–21; RHock, The Social Context of Paul’s Ministry: Tentmaking and Apostleship ’80.—M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0325-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκῆνος, ους, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σκῆνος</span>, <span class=\"greek\">ους</span>, <span class=\"greek\">τό</span> (Pré-socr., Hippocr.+; inscr.; Wsd 9:15) uma morada temporária em oposição a uma estrutura permanente, tenda, alojamento, extensão fig. do sentido prim. ‘tenda’, que não se encontra em nossa lit.: do corpo (Democr. [Vorsokrat. índice] et al.; Ps.-Pla., Axioch. 365e; 366a; Herm. Wr. 13, 12; 15; Achilles Tat. 2, 36, 3 <span class=\"greek\">τὸ</span> <span class=\"greek\">οὐράνιον</span> <span class=\"greek\">θνητῷ</span> <span class=\"greek\">σκήνει</span> <span class=\"greek\">δεδεμένον</span>; CIG 1656 <span class=\"greek\">σκῆνος</span> <span class=\"greek\">μὲν</span> … , <span class=\"greek\">ψυχὴ</span> <span class=\"greek\">δέ</span>; 3123; 6309; PGM 1, 319; 4, 1951; 1970; Wsd 9:15) <span class=\"greek\">εἶναι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ς</span>. estar em sua tenda, i.e., estar fisicamente vivo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.5.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 5:4</a>. <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐπίγειος</span> <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">οἰκία</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ς</span>. a tenda terrestre em que habitamos v. 1 (sobre a combinação de gen. v. B-D-F §168, 1; Rob. 498; sobre a imagem Straub 84f).—V. <span class=\"greek\">γυμνός</span> 3, fim.—DELG s.v. <span class=\"greek\">σκηνή</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0325-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκηνόω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σκηνόω</span> (<span class=\"greek\">σκηνή</span>) fut. <span class=\"greek\">σκηνώσω</span>; 1 aor. <span class=\"greek\">ἐσκήνωσα</span> (X., Pla. et al.; LXX; Jos., Vi. 244, Ant. 3, 293) viver, estabelecer-se, fixar residência (X., Demosth. 54, 3; SIG 344, 3; PSI 340, 10; 13 [III a.C.]; LXX) com <span class=\"greek\">ἐν</span> e o dat. de lugar (X., An. 5, 5, 11; PEdg 68 [=Sb 6774], 7; Gen 13:12) <span class=\"greek\">ἐν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">οὐρανῷ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.13.6\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 13:6</a>; cf. 12:12 <span class=\"greek\">ἐν</span> <span class=\"greek\">ἡμῖν</span> entre nós (talvez uma expressão de continuidade com o ‘armar a tenda’ de Deus em Israel) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:14</a> (Iren. 1, 9, 2 [Harv. I 82, 9]; Diogenes, Ep. 37, 1 <span class=\"greek\">παρὰ</span> <span class=\"greek\">τούτοις</span> <span class=\"greek\">ἐσκήνωσα</span>=‘fixei residência com eles’). <span class=\"greek\">μετ</span>’ <span class=\"greek\">αὐτῶν</span> com eles <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.3\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 21:3</a>. <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">αὐτούς</span> sobre ou acima deles, i.e., abrigá-los, de Deus (v. <span class=\"greek\">σκηνή</span> 1b<span class=\"greek\">α</span>) 7:15.—DELG s.v. <span class=\"greek\">σκηνή</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0325-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκήνωμα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σκήνωμα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (<span class=\"greek\">σκηνόω</span>; Eur., X. et al.; LXX; TestJob 43:7, 11; ParJer; ApcSed 9; Jos., Ant. 11, 187) ger. ‘alojamento, morada’, em nossa lit. somente metaf. habitação</p><p class=\"entry-text\">ⓐ de um povo <span class=\"greek\">σκήνωμα</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">οἴκῳ</span> <span class=\"greek\">Ἰακώβ</span> uma habitação para a casa de Jacó <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.46\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:46</a> (segundo Ps 131:5, mas com <span class=\"greek\">οἴκῳ</span> em lugar de <span class=\"greek\">θεῷ</span>). Para esta leitura do texto v. Metzger 351–53, lit. n. 11.</p><p class=\"entry-text\">ⓑ de Deus (Paus. 3, 17, 6; LXX) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.46\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:46</a> pertence aqui se <span class=\"greek\">σκήνωμα</span> no texto citado acima deve ser entendido em ref. a uma habitação compartilhada por Deus, e esp. se <span class=\"greek\">θεῷ</span> em vez de <span class=\"greek\">Ἰακώβ</span> for preferido, caso em que a habitação é para Deus somente.</p><p class=\"entry-text\">ⓒ do corpo (Ps.-Callisth. 1, 24, 11; Herm. Wr. em Stob., Flor. I 396, 1 W.=p. 476, 3 Sc.; escólio sobre Nicander, Ther. 694; PGM 19a, 49; Sextus 320; v. <span class=\"greek\">σκῆνος</span>) <span class=\"greek\">εἶναι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τούτῳ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">σκ</span>.=permanecer vivo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:13</a> (cf. a inscr. cristã tardia IG X/2, 1, 397, 6f, v. New Docs 4, 172); op. <span class=\"greek\">ἡ</span> <span class=\"greek\">ἀπόθεσις</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">σκ</span>.=morte v. 14. <span class=\"greek\">ἡ</span> <span class=\"greek\">ψυχὴ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">θνητῷ</span> <span class=\"greek\">σκηνώματι</span> <span class=\"greek\">κατοικεῖ</span> Dg 6:8 (Sext., loc. cit. <span class=\"greek\">τὸ</span> <span class=\"greek\">ς</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">ψυχῆς</span>).—DELG s.v. <span class=\"greek\">σκηνή</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0325-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκῆπτρον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σκῆπτρον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (<span class=\"greek\">σκήπτομαι</span> ‘apoiar-se (em)’, p. ex., um bastão; Hom.+; inscr.; PGM 13, 182; 187; LXX; TestSol; Test12Patr)</p><p class=\"entry-text\">① cetro como símbolo do poder de governar (TestJud 24:5; JosAs 5:6; Ant. 17, 197) <span class=\"greek\">σκ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">μεγαλωσύνης</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> o cetro da majestade de Deus 1 Cl 16:2 (cf. Esth 4:17q; Ezk. Trag. 71 em Eus., PE 9, 29, 5; Philo, Mut. Nom. 136; SibOr 3, 49. O cetro de Zeus Pind., P. 1, 6; Cornutus 9 p. 10, 10; Iambl., Vi. Pyth. 28, 155; de Reia Pind., N. 11, 4; de Ísis IAndrosIsis, Cyrene 6 p. 129; de Selene PGM 4, 2843f.—FdeWaele, The Magic Staff or Rod in Graeco-Italian Antiquity 1927, cap. 1).</p><p class=\"entry-text\">② tribo, por metonímia, das tribos de Israel (1 Km 2:28; 9:21; 3 Km 11:31f, 35f al.; Jos., Ant. 6, 61; TestJud 25:1; TestNapht 5:8) 1 Cl 32:2.—DELG s.v. <span class=\"greek\">σκήπτομαι</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0325-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκιά, ᾶς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σκιά</span>, <span class=\"greek\">ᾶς</span>, <span class=\"greek\">ἡ</span> (Hom.+; inscr., pap., LXX; ParJer 3: 14; 5:1 Philo; Jos., Bell. 2, 28 <span class=\"greek\">σκιά</span>-<span class=\"greek\">σῶμα</span>, Ant. 5, 238; 10, 29; Just., Mel., Ath.).</p><p class=\"entry-text\">① sombra ou abrigo da luz e de qualquer calor a ela associado, sombra <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:32</a> (cf. Ezk 17:23; ParJer, Just., Ath.).</p><p class=\"entry-text\">② a forma projetada por um objeto ao interceptar raios de luz, sombra</p><p class=\"entry-text\">ⓐ lit. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:15</a></p><p class=\"entry-text\">ⓑ fig. (v. <span class=\"greek\">σκότος</span> 3.—Jos., Bell. 1, 215) <span class=\"greek\">σκιὰ</span> <span class=\"greek\">θανάτου</span> sombra da morte (Job 12:22; Ps 22:4; 43:20; Jer 13:16; Mel., P. 56, 409 <span class=\"greek\">τὰς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θανάτου</span> <span class=\"greek\">σκιάς</span>.—Assim também <span class=\"greek\">σκιά</span> por si só, da sombra da morte, que está ao lado de um ancião: Herodas 1, 16) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:16</a> (Is 9:1); com <span class=\"greek\">σκότος</span> (Job 3:5; Ps 106:10, 14) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.79\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:79</a> (Ps 106, 10; v. New Docs 4, 149). Em lugar de <span class=\"greek\">σκοτία</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">1J 2:8</a> v.l.</p><p class=\"entry-text\">③ mera representação de algo real, sombra (do sentido de aspecto insubstancial, p. ex., sombras dos mortos: Od. 10, 495; Aeschyl., Eum. 302, desenvolve-se a ideia de um contraste entre imagem e realidade: Prodicus [V a.C.] Fgm. 2 [em X., Mem. 2, 1, 22]; Achilles Tat. 1, 15, 6 <span class=\"greek\">τὸ</span> <span class=\"greek\">ὕδωρ</span> <span class=\"greek\">ἦν</span> <span class=\"greek\">κάτοπτρον</span>, <span class=\"greek\">ὡς</span> <span class=\"greek\">δοκεῖν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἄλσος</span> <span class=\"greek\">εἶναι</span> <span class=\"greek\">διπλοῦν</span>, <span class=\"greek\">τὸ</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἀληθείας</span>, <span class=\"greek\">τὸ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">σκιᾶς</span> ‘a água servia de espelho, sugerindo que o bosque era duplo, um real e o outro um reflexo’; Phalaris, Ep. 35 <span class=\"greek\">λόγος</span> <span class=\"greek\">ἔργου</span> <span class=\"greek\">σκ</span>. Freq. em Philo: Somn. 1, 206, Plant. 27; Leg. All. 3, 102, Post. Caini 112) <span class=\"greek\">σκιὰ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">μελλόντων</span> uma sombra do que há de vir <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:17</a> (op. <span class=\"greek\">τὸ</span> <span class=\"greek\">σῶμα</span>, como Philo, Conf. Lingu. 190; Jos., Bell. 2, 28; Lucian, Hermot. 79). <span class=\"greek\">ὑπόδειγμα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">σκιὰ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἐπουρανίων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.8.5\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 8:5</a> (Synes., Ep. 44 p. 182d <span class=\"greek\">τοῦ</span> <span class=\"greek\">θείου</span> <span class=\"greek\">σκ</span>. <span class=\"greek\">τὸ</span> <span class=\"greek\">ἀνθρώπινον</span>; LHurst, JTS 34, ’83, 163–65). <span class=\"greek\">σκιά</span> contrasta com <span class=\"greek\">εἰκών</span> (v. <span class=\"greek\">εἰκών</span> 3) 10:1.—B. 62.—DELG. M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0325-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκιρτάω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σκιρτάω</span> fut. 2 pl. <span class=\"greek\">σκιρτήσετε</span> Mal 3:20; 1 aor. <span class=\"greek\">ἐσκίρτησα</span> (Hom. et al.; PGM 3, 200; LXX; Philo, Spec. Leg. 1, 304) movimento exuberante de salto, saltar, dar saltos como sinal de alegria (Jer 27:11; Mal 3:20; Jos., Bell. 5, 120) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:23</a>; AcPl Ha 3, 18. De ovelhas que saltitam alegremente (cf. Dio Chrys. 69 [19], 3; Longus 1, 9,1; Theophyl. Sim., Ep. 29; Eutecnius 1 p. 18, 3) Hs 6, 1, 6; 6, 2, 3 f; 6. <span class=\"greek\">ἐκκλησίας</span> <span class=\"greek\">χάρις</span> <span class=\"greek\">σκιρτᾷ</span> Dg 11:6. Dos movimentos de uma criança no ventre (Gen 25:22. V. ENorden, Die Geburt des Kindes 1924 p. 104, 1), que são tomados como expressão de alegria <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.41\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:41</a>, 44; GJs 12:2.—Metaf. <span class=\"greek\">καὶ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ὕδατα</span> <span class=\"greek\">ταῦτα</span> <span class=\"greek\">γαληνιῶντα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">σκιρτῶντα</span> estas águas, primeiro calmas e depois ondulantes, com sugestão de vida em contraste com a esterilidade de Ana GJs 3:3.—DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0325-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκληροκαρδία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σκληροκαρδία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (uma formação correta, mas modelada segundo <span class=\"hebrew\">עָרְלַת</span> <span class=\"hebrew\">לֵבָב</span> Dt 10:16; Jer 4:4; Sir 16:10; En 16:3; TestSim 6:2 v.l.; Philo, Spec. Leg. 1, 305; Just.; Did., Gen 233, 10.—B-D-F §120, 4; Mlt-H. 279) disposição mental inflexível, dureza de coração, frieza, obstinação, teimosia <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:5</a>; Hv 3, 7, 6 (Leutzsch, Hermas 419 n. 374); B 9:5 (segundo Dt 10:16; Jer 4:4). Com <span class=\"greek\">ἀπιστία</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.16.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 16:14</a>.—EDNT. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0325-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκληρός, ά, όν</h1><div class=\"entry-meta\"><span>adjetivo; substantivado</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σκληρός</span>, <span class=\"greek\">ά</span>, <span class=\"greek\">όν</span> (<span class=\"greek\">σκέλλομαι</span> ‘estar ressequido, estar seco’; Hes., Hdt.+; ‘duro [ao tato], áspero’)</p><p class=\"entry-text\">① relativo a ser externamente duro ou áspero, duro (ao tato), áspero, de coisas <span class=\"greek\">λίθοι</span> duros (OGI 194, 28; Wsd 11:4) Hs 9, 6, 8; 9, 8, 6ab. <span class=\"greek\">ῥάβδος</span> áspera, de um bastão nodoso (v. Pind., O. 7, 29; Diógenes, o Cínico [IV a.C.] em Diog. L. 6, 21 <span class=\"greek\">σκληρὸν</span> <span class=\"greek\">ξύλον</span>=um bastão duro; Aelian, VH 10, 16) 6, 2, 5.</p><p class=\"entry-text\">② relativo a causar uma reação adversa por ser duro ou áspero, duro, áspero, desagradável, extensão fig. de 1, de palavras (Demetrius em Stob., Flor. 3, 8, 20 vol. III p. 345 H.; Diogenes, Ep. 21; Gen 21:11; 42:7; Dt 1:17; En) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.60\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:60</a>; Jd 15 (segundo En 1:9); v. Hv 1, 4, 2 (com <span class=\"greek\">χαλεπός</span>). <span class=\"greek\">ἐντολαί</span> duras, difíceis (Diod S 14, 105, 2 <span class=\"greek\">σκ</span>. <span class=\"greek\">πρόσταγμα</span>; Porphyr., Vi. Pyth. 8 <span class=\"greek\">προστάγματα</span>) Hm 12, 3, 4f; 12, 4, 4 (com <span class=\"greek\">δύσβατος</span>). <span class=\"greek\">ἄνεμοι</span> impetuosos, fortes (Aelian, VH 9, 14; Pollux 1, 110; Procop., Bell. 3, 13, 5; Pr 27:16) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">Js 3:4</a>.</p><p class=\"entry-text\">③ relativo a ser difícil a ponto de ser impossível, duro, implicando uma força adversa inflexível, o neut.: <span class=\"greek\">σκληρόν</span> <span class=\"greek\">σοι</span> (sc. <span class=\"greek\">ἐστίν</span>) é duro para ti, seguido de inf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:4</a> v.l., 6 v.l.; 26:14.</p><p class=\"entry-text\">④ relativo a ser inflexível em comportamento ou atitude</p><p class=\"entry-text\">ⓐ de pess., no trato com outros, duro, severo, áspero, cruel, impiedoso (Soph., Pla. et al.; OGI 194, 14; 1 Km 25:3; Is 19:4; 48:4; PsSol 4:2; EpArist 289; Mel., P. 20, 138) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:24</a>. Do diabo Hm 12, 5, 1.</p><p class=\"entry-text\">ⓑ em resposta a um apelo à mudança de mentalidade, subst. <span class=\"greek\">τὸ</span> <span class=\"greek\">σκληρόν</span> obstinação com gen. (Polyb. 4, 21, 1; Jos., Ant. 16, 151 <span class=\"greek\">τὸ</span> <span class=\"greek\">σκ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">τρόπου</span>) <span class=\"greek\">τὸ</span> <span class=\"greek\">σκ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">καρδίας</span> a dureza de coração B 9:5 v.l. (em lugar de <span class=\"greek\">σκληροκαρδία</span>, q.v.).—Sobre a história da palavra v. KDieterich, RhM, n.s. 60, 1905, 236ff; FDanker, Hardness of Heart, CTM 44, ’73, 89–100, Deafness and Hearing in the Bible, em The Word in Signs and Wonders, ed. DPokorny/RHohenstein ’77, 25–37.—B. 1064.—DELG s.v. <span class=\"greek\">σκέλλομαι</span>. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0325-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκληρότης, ητος, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σκληρότης</span>, <span class=\"greek\">ητος</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">σκληρός</span>; Antiphon, Pla. et al.; LXX, Philo; Jos., Ant. 3, 2) dureza (de coração), obstinação como característica humana (Pla., Rep. 3, 410d; 10, 607b; Aristot., Poet. 15, 11; Dt 9:27; Philo, Spec. Leg. 304) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:5</a>. Do espírito de aspereza, rudeza com o qual o Espírito Santo não pode viver Hm 5, 2, 6 (cf. Antiphon Or. 3, 3, 4 <span class=\"greek\">σκλ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">δαίμονος</span>).—DELG s.v. <span class=\"greek\">σκέλλομαι</span>. M-M. TW. Spicq.</p></section></article>"};
